func TestEnumRecommendationString(t *testing.T) {
	t.Run("NewFromString_RECOMMENDED", func(t *testing.T) {
		t.Parallel()
		val, err := NewRecommendationStringFromString("RECOMMENDED")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, RecommendationString("RECOMMENDED"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_NOT_RECOMMENDED", func(t *testing.T) {
		t.Parallel()
		val, err := NewRecommendationStringFromString("NOT_RECOMMENDED")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, RecommendationString("NOT_RECOMMENDED"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_UNKNOWN", func(t *testing.T) {
		t.Parallel()
		val, err := NewRecommendationStringFromString("UNKNOWN")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, RecommendationString("UNKNOWN"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewRecommendationStringFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewRecommendationStringFromString("RECOMMENDED")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

